android.extraProguardRules:
-keepattributes *Annotation*,Signature,InnerClasses,EnclosingMethod
-keepattributes SourceFile,LineNumberTable
-keep class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.react.bridge.JavaScriptModule { *; }
-keep class com.facebook.react.bridge.NativeModule { *; }
-keepclassmembers class * extends com.facebook.react.bridge.NativeModule { <methods>; }
-keepclassmembers class * { @com.facebook.react.bridge.ReactMethod *; @com.facebook.react.bridge.ReactProp *; @com.facebook.react.bridge.ReactPropGroup *; }
-keep class com.facebook.react.defaults.** { *; }
-keep class com.facebook.react.ReactHost { *; }
-keep class com.facebook.react.ReactNativeHost { *; }
-keep class com.facebook.react.bridge.ReactMarker { *; }
-keep @com.facebook.proguard.annotations.DoNotStrip class * { *; }
-keepclassmembers class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keepclassmembers class * { native <methods>; }
-keep class com.swmansion.reanimated.** { *; }
-keepclassmembers class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.worklets.** { *; }
-keepclassmembers class com.swmansion.worklets.** { *; }
-keep class com.swmansion.gesturehandler.** { *; }
-keep class com.swmansion.rnscreens.** { *; }
-keepclassmembers class com.swmansion.rnscreens.** { *; }
-keep class com.horcrux.svg.** { *; }
-keep class com.tencent.mmkv.** { *; }
-keep class com.mrousavy.mmkv.** { *; }
-keep class com.reactnativegooglesignin.** { *; }
-keep class com.google.android.gms.auth.api.signin.** { *; }
-keep class com.google.android.gms.common.api.** { *; }
-keepclassmembers class com.google.android.gms.common.api.** { *; }
-keep class com.google.firebase.** { *; }
-keep class expo.modules.notifications.** { *; }
-keep class expo.modules.av.** { *; }
-keep class com.google.android.exoplayer2.** { *; }
-keep interface com.google.android.exoplayer2.** { *; }
-keep class expo.modules.** { *; }
-keep @expo.modules.core.interfaces.DoNotStrip class * { *; }
-keepclassmembers class * { @expo.modules.core.interfaces.DoNotStrip *; }
-keep class * extends expo.modules.kotlin.modules.Module
-keep class * implements expo.modules.kotlin.records.Record { *; }
-keep class * extends expo.modules.kotlin.sharedobjects.SharedObject
-keep class * implements expo.modules.kotlin.views.ExpoView { *; }
-dontwarn javax.annotation.**
-dontwarn org.checkerframework.**
-dontwarn com.google.firebase.ktx.Firebase
-dontwarn expo.modules.core.interfaces.services.KeepAwakeManager
